export const DAME=Object.freeze({name:'Dame Dash',special:'Achoo!',kind:'dameAchoo',duration:1.65,range:850,color:'#d0ae75',glow:'rgba(208,174,117,.4)'});
export const DEBT='dameDebtBall';
export function damePose(f){const t=Math.max(0,f.stateTime||0),p=f.attackProgress||0;let i=0;if(f.state==='special')i=t<.32?1:t<.72?14:t<1.18?15:0;else if(f.state==='punch')i=p<.3?4:p<.78?5:0;else if(f.state==='kick')i=p<.32?6:p<.92?7:0;else if(f.state==='ko')i=t<.25?12:13;else if(['hurt','grabbed','beltHeld'].includes(f.state))i=t<.18?10:11;else if(f.state==='block')i=4;else if(!f.grounded||['jump','fall'].includes(f.state))i=f.vy>0?9:8;else if(['walk','run'].includes(f.state))i=2+Math.floor(t*9)%2;else i=Math.floor(t*3)%2;return {key:'damedash',index:i};}
export function createDebt(f){return {kind:DEBT,basic:true,owner:f.id,facing:f.facing,originX:f.x,x:f.x+60*f.facing,y:f.y+35,age:0,ttl:.58,duration:.58,active:true,delay:0,hitCount:0};}
export function createAchoo(f){return {kind:DAME.kind,owner:f.id,facing:f.facing,originX:f.x,x:f.x+35*f.facing,y:f.y+157,age:0,ttl:DAME.duration,duration:DAME.duration,active:true,delay:0,hitCount:0};}
export function endAchoo(g,a,s){s.active=false;s.ttl=0;if(a){a.actionRemaining=0;a.vx=0;g.setState(a,a.hp>0?'idle':'ko');}}
export function updateDame(g,s,a,b,dt){if(!a||!b){s.active=false;s.ttl=0;return;}if(s.kind===DEBT){const old=s.x,p=Math.min(1,s.age/.58);s.x=s.originX+s.facing*(60+Math.sin(p*Math.PI)*255);if(!s.hitCount&&p<=.5&&b.x>=Math.min(old,s.x)-45&&b.x<=Math.max(old,s.x)+45&&Math.abs(b.y-(s.y-35))<100&&(b.x-s.originX)*s.facing>=0){if(g.hit(a,b,15,'kick',265,.25,s.originX))s.hitCount=1;}if(s.ttl<=0)s.active=false;return;}a.facing=s.facing;a.vx=0;if(s.ttl>1e-9){a.state='special';a.actionRemaining=Math.max(a.actionRemaining,s.ttl);}if(s.age>=.42){const old=s.x;s.x=s.originX+s.facing*(35+(s.age-.42)*720);if(!s.hitCount&&b.x>=Math.min(old,s.x)-45&&b.x<=Math.max(old,s.x)+45&&Math.abs((b.y+105)-s.y)<105&&(b.x-s.originX)*s.facing>=0){if(g.hit(a,b,35,DAME.kind,320,.33,s.originX))s.hitCount=1;}}if(s.ttl<=1e-9)endAchoo(g,a,s);}
export function drawDame(ctx,s,game,ground){ctx.save();if(s.kind===DEBT){const x=s.x,y=ground-s.y,a=game.fighters.find(f=>f.id===s.owner);if(a){ctx.lineWidth=5;ctx.strokeStyle='#29272b';ctx.beginPath();ctx.moveTo(a.x,ground-a.y-12);ctx.quadraticCurveTo((a.x+x)/2,ground-a.y+4,x,y);ctx.stroke();const d=Math.abs(x-a.x);for(let i=0;i<Math.max(1,Math.floor(d/13));i++){const p=i/Math.max(1,Math.floor(d/13)),xx=a.x+(x-a.x)*p,yy=ground-a.y-12+(y-(ground-a.y-12))*p+Math.sin(p*Math.PI)*9;ctx.beginPath();ctx.ellipse(xx,yy,8,4,(i%2)*.8,0,Math.PI*2);ctx.strokeStyle='#c4bec0';ctx.lineWidth=2;ctx.stroke();}}const grd=ctx.createRadialGradient(x-10,y-13,2,x,y,32);grd.addColorStop(0,'#a9a0a9');grd.addColorStop(.38,'#423b43');grd.addColorStop(1,'#151318');ctx.fillStyle=grd;ctx.strokeStyle='#aaa0a6';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x,y,30,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#fff4df';ctx.font='bold 17px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('DEBT',x,y);ctx.restore();return;}if(s.age>=.28&&s.age<.85){ctx.font='900 31px sans-serif';ctx.textAlign='center';ctx.lineWidth=6;ctx.strokeStyle='#211822';ctx.fillStyle='#ffe652';ctx.strokeText('ACHOO!',s.originX,ground-250);ctx.fillText('ACHOO!',s.originX,ground-250);}if(s.age>=.42&&!s.hitCount){for(let i=0;i<3;i++){let x=s.x-s.facing*i*32,y=ground-s.y+(i-1)*20;ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(s.age*12+i)*.35);ctx.fillStyle='#fff7e4';ctx.strokeStyle='#59443c';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-11,-7);ctx.bezierCurveTo(-15,-18,-4,-19,0,-14);ctx.bezierCurveTo(7,-19,16,-14,12,-5);ctx.lineTo(7,9);ctx.quadraticCurveTo(4,15,1,5);ctx.quadraticCurveTo(-1,0,-4,8);ctx.quadraticCurveTo(-7,15,-10,7);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}}ctx.restore();}
